def choose_api(workload):
    mapping = {
        "documentos_json_nativo": "API for NoSQL",
        "migracion_mongodb": "API for MongoDB",
        "consultas_cql_cassandra": "API for Apache Cassandra",
        "grafos_y_relaciones": "API for Apache Gremlin",
        "migracion_table_storage": "API for Table",
    }
    return mapping.get(workload, "API for NoSQL")

workloads = [
    "documentos_json_nativo",
    "migracion_mongodb",
    "grafos_y_relaciones",
    "consultas_cql_cassandra",
    "migracion_table_storage",
]
for w in workloads:
    print(f"{w} -> {choose_api(w)}")
